<?php
/** Separate operational copies from the existing official invoice. All amounts are core values. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Jalali,Money};
if(!defined('ABSPATH'))exit;
Ctx::need($res.'.export');
$titles=['store'=>'نسخهٔ فروشگاه','customer'=>'نسخهٔ مشتری','workshop'=>'برگهٔ کارگاه','receipt'=>'رسید فروشگاهی ۸۰ میلی‌متری'];
$workshop=$printLayout==='workshop';$receipt=$printLayout==='receipt';
?>
<div class="erp-no-print erp-print-actions"><button type="button" class="btn btn-primary" onclick="window.print()">چاپ / ذخیره PDF</button><a class="btn btn-outline" href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'invoice_view','id'=>$d['id']])); ?>">بازگشت به برگه</a><p>برای چاپ رسید، اندازهٔ کاغذ چاپگر را ۸۰ میلی‌متر تنظیم کنید. چاپ مستقیم بدون پنجرهٔ مرورگر در این خروجی پیاده نشده است.</p></div>
<section class="erp-card erp-invoice-print erp-operational-copy <?php echo $receipt?'erp-receipt-copy':''; ?>">
<h2><?php echo esc_html($company['legal_name']?:$company['name']); ?></h2><h3><?php echo esc_html($titles[$printLayout]); ?></h3>
<p><?php echo esc_html(\Agah\Erp\Modules\Trade\InvoiceService::KINDS[$kind]); ?> — شماره: <?php echo esc_html($d['number']===null?'پیش‌نویس #'.Money::toFa($d['id']):Money::toFa($d['number'])); ?></p>
<?php if($d['status']!=='issued'): ?><p class="erp-print-state"><?php echo $d['status']==='void'?'باطل‌شده؛ فاقد اعتبار':'پیش‌نویس؛ هنوز صادر نشده است'; ?></p><?php endif; ?>
<p>تاریخ برگه: <?php echo esc_html(Jalali::format($d['invoice_date'])); ?> — سررسید: <?php echo esc_html(Jalali::format($d['due_date'])); ?></p>
<p>طرف حساب: <?php echo esc_html($party['name']); ?></p>
<?php if(!$workshop): ?><p>تلفن: <?php echo esc_html($party['phone']??''); ?></p><p>نشانی: <?php echo esc_html($party['address']??''); ?></p><p>واحد مبالغ: <?php echo Ctx::unit()==='rial'?'ریال':'تومان'; ?></p><?php endif; ?>
<?php if($receipt): ?>
<?php foreach($d['lines'] as $line): ?><article class="erp-receipt-line"><strong><?php echo esc_html($line['item_name']); ?></strong><p>کد: <?php echo esc_html($line['item_code']??''); ?></p><p>مقدار: <?php echo esc_html(Money::toFa(Money::qtyToDb((int)$line['qty_scaled'])).' '.$line['unit_name']); ?></p><p>فی: <bdi dir="ltr"><?php echo esc_html(Money::fmt((int)$line['unit_price'],Ctx::unit())); ?></bdi></p><p>جمع ردیف: <bdi dir="ltr"><?php echo esc_html(Money::fmt(Money::add(Money::add((int)$line['net_amount'],(int)$line['tax_amount']),(int)$line['extra_cost']),Ctx::unit())); ?></bdi></p></article><?php endforeach; ?>
<?php else: ?>
<table class="erp-table erp-copy-items"><colgroup><?php if(!$workshop): ?><col style="width:36%"><col style="width:16%"><col style="width:24%"><col style="width:24%"><?php endif; ?></colgroup><thead><tr><?php if($workshop): ?><th>ردیف</th><th>کالا / خدمت</th><th>واحد</th><th>مقدار</th><?php else: ?><th>کالا / خدمت</th><th>مقدار / واحد</th><th>فی</th><th>جمع نهایی ردیف</th><?php endif; ?></tr></thead><tbody>
<?php foreach($d['lines'] as $line): ?><tr><?php if($workshop): ?><td><?php echo esc_html(Money::toFa($line['line_no'])); ?></td><?php endif; ?><td><?php echo esc_html(($line['item_code']??'').' — '.$line['item_name']); ?></td><?php if($workshop): ?><td><?php echo esc_html($line['unit_name']); ?></td><?php endif; ?><td><?php echo esc_html(Money::toFa(Money::qtyToDb((int)$line['qty_scaled']))); ?><?php if(!$workshop): ?><small><?php echo esc_html($line['unit_name']); ?></small><?php endif; ?></td><?php if(!$workshop): ?><td class="erp-copy-number"><bdi dir="ltr"><?php echo esc_html(Money::fmt((int)$line['unit_price'],Ctx::unit())); ?></bdi></td><td class="erp-copy-number"><bdi dir="ltr"><?php echo esc_html(Money::fmt(Money::add(Money::add((int)$line['net_amount'],(int)$line['tax_amount']),(int)$line['extra_cost']),Ctx::unit())); ?></bdi></td><?php endif; ?></tr><?php endforeach; ?>
</tbody></table><?php endif; ?>
<?php if(!$workshop): ?><dl class="erp-copy-total"><?php foreach(['discount_amount'=>'تخفیف ردیف‌ها','header_discount'=>'تخفیف کل','tax_amount'=>'مالیات و عوارض','extra_cost'=>'هزینهٔ جانبی'] as $key=>$label): ?><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html(Money::fmt($sum[$key],Ctx::unit())); ?></dd><?php endforeach; ?><dt>مبلغ نهایی برگه</dt><dd><strong><?php echo esc_html(Money::fmt((int)$d['amount'],Ctx::unit())); ?></strong></dd></dl><p>این نسخهٔ عملیاتی جایگزین صورتحساب رسمی یا تأیید پرداخت نیست.</p><?php endif; ?>
<?php if($d['description']!==''): ?><p>توضیحات: <?php echo esc_html($d['description']); ?></p><?php endif; ?>
<div class="erp-copy-signatures"><span>تهیه‌کننده / تحویل‌دهنده</span><span>دریافت‌کننده</span></div>
</section>
<style>
.erp-operational-copy{max-width:760px;margin:16px auto;font-size:14px}.erp-copy-items{width:100%;min-width:0;table-layout:fixed}.erp-copy-items th,.erp-copy-items td{white-space:normal;overflow-wrap:anywhere;padding:6px;border:1px solid #777}.erp-copy-number{white-space:nowrap!important;overflow-wrap:normal!important;font-variant-numeric:tabular-nums}.erp-receipt-line{border-block:1px dashed #777;padding-block:8px;break-inside:avoid}.erp-receipt-line p{margin:4px 0}.erp-copy-total{display:grid;grid-template-columns:1fr 1fr;gap:8px}.erp-copy-total dd{margin:0}.erp-print-state{font-weight:bold;border:2px solid currentColor;padding:8px}.erp-copy-signatures{display:flex;justify-content:space-between;margin-top:28px;min-height:48px}.erp-receipt-copy{max-width:80mm;font-size:11px;padding:4mm}.erp-receipt-copy .erp-copy-items{font-size:10px}.erp-receipt-copy .erp-copy-items td,.erp-receipt-copy .erp-copy-items th{padding:3px}.erp-receipt-copy h2{font-size:18px}
@media print{@page{size:<?php echo $receipt?'80mm 297mm':'A5 portrait'; ?>;margin:<?php echo $receipt?'4mm':'8mm'; ?>}html,body{min-width:0!important}body:has(.erp-operational-copy),body:has(.erp-operational-copy) *{background:transparent!important;color:#000!important;box-shadow:none!important}html,body,.erp,.erp-workspace,.erp-workspace-content{background:#fff!important;color:#000!important}.erp .erp-operational-copy{width:100%!important;max-width:none!important;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important}.erp .erp-copy-items{min-width:0!important;width:100%!important}.erp .erp-copy-items tr{break-inside:avoid}.erp .erp-operational-copy h2{font-size:14pt}.erp .erp-copy-items thead{display:table-header-group}}
</style>
